{
"title": "Infrastructure: Host CPU / Memory and Regional Network Traffic",
"timeRange": {"from": "now-1h", "to": "now"},
"refreshIntervalMs": 15000,
"panels": [
{
"title": "CPU usage per host",
"description": "Average CPU utilization in percent for each host, grouped into one-minute buckets over time.",
"viz": "line",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, host, avg(cpu_pct) AS cpu_pct FROM system_metrics GROUP BY minute, host ORDER BY minute",
"timeField": "minute"
},
"format": "percent",
"options": {"legend": "bottom", "decimals": 1, "yAxis": {"min": 0, "max": 100, "label": "CPU %"}},
"layout": {"x": 0, "y": 0, "w": 6, "h": 4}
,
"refreshIntervalMs": 15000
,
"timeRange": {"from": "now-1h", "to": "now"}
,
"id": "panel-cpu-per-host"
},
{
"title": "Memory usage per host",
"description": "Average memory utilization in percent for each host, grouped into one-minute buckets over time.",
"viz": "line",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, host, avg(mem_pct) AS mem_pct FROM system_metrics GROUP BY minute, host ORDER BY minute",
"timeField": "minute"
},
"format": "percent",
"options": {"legend": "bottom", "decimals": 1, "yAxis": {"min": 0, "max": 100, "label": "Memory %"}},
"layout": {"x": 6, "y": 0, "w": 6, "h": 4}
,
"refreshIntervalMs": 15000
,
"timeRange": {"from": "now-1h", "to": "now"}
,
"id": "panel-mem-per-host"
},
{
"title": "Network in bytes by region",
"description": "Total inbound network bytes summed per region, grouped into one-minute buckets over time.",
"viz": "area",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, region, sum(net_in_bytes) AS net_in_bytes FROM system_metrics GROUP BY minute, region ORDER BY minute",
"timeField": "minute"
},
"format": "bytes",
"options": {"legend": "bottom", "stacked": true, "compact": true, "yAxis": {"label": "Bytes in"}},
"layout": {"x": 0, "y": 4, "w": 6, "h": 4}
,
"refreshIntervalMs": 15000
,
"timeRange": {"from": "now-1h", "to": "now"}
,
"id": "panel-net-in-region"
},
{
"title": "Network out bytes by region",
"description": "Total outbound network bytes summed per region, grouped into one-minute buckets over time.",
"viz": "area",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, region, sum(net_out_bytes) AS net_out_bytes FROM system_metrics GROUP BY minute, region ORDER BY minute",
"timeField": "minute"
},
"format": "bytes",
"options": {"legend": "bottom", "stacked": true, "compact": true, "yAxis": {"label": "Bytes out"}},
"layout": {"x": 6, "y": 4, "w": 6, "h": 4}
,
"refreshIntervalMs": 15000
,
"timeRange": {"from": "now-1h", "to": "now"}
,
"id": "panel-net-out-region"
}
]
}
